descriptor.templateCss:
* { box-sizing: border-box; }
.cop-widget {
    display: flex;
    flex-direction: column;
    width: 100%;
    height: 100%;
    font-family: 'Roboto', sans-serif;
    background: #ffffff;
    padding: 10px 12px;
    overflow: hidden;
}
.cop-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex: 0 0 auto;
    padding-bottom: 8px;
    border-bottom: 1px solid #78909c;
    margin-bottom: 6px;
}
.cop-title {
    font-size: 14px;
    font-weight: 700;
    color: #263238;
}
.cop-header-derecha {
    display: flex;
    align-items: center;
    gap: 10px;
}
.cop-total {
    font-size: 13px;
    font-weight: 700;
    color: #0d47a1;
    white-space: nowrap;
}
#cop-btn-refrescar {
    border: none;
    background: #0d47a1;
    color: #ffffff;
    border-radius: 4px;
    width: 24px;
    height: 24px;
    font-size: 13px;
    cursor: pointer;
    line-height: 1;
    display: flex;
    align-items: center;
    justify-content: center;
}
#cop-btn-refrescar:hover { background: #0a3880; }
#cop-btn-refrescar:disabled { opacity: 0.6; cursor: default; }
.cop-lista {
    flex: 1 1 auto;
    min-height: 0;
    overflow-y: auto;
}
.cop-cargando, .cop-vacio, .cop-error {
    padding: 14px 4px;
    font-size: 13px;
    color: #546e7a;
    text-align: center;
}
.cop-error { color: #b71c1c; font-weight: 600; }
/* Un solo caudalímetro: solo se muestra el nombre y el valor, sin selector
   de signo -- con uno solo no hay nada que combinar. */
.cop-fila-unica {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 10px 4px;
    font-size: 14px;
}
.cop-fila-unica .cop-nombre { font-weight: 600; color: #263238; }
.cop-fila-unica .cop-valor { font-weight: 700; color: #0d47a1; }
/* Varios caudalímetros: cada uno con su valor y el selector +/- */
.cop-fila {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 8px 4px;
    border-bottom: 1px solid #cfd8dc;
}
.cop-fila:last-child { border-bottom: none; }
.cop-nombre {
    flex: 1 1 auto;
    min-width: 0;
    font-size: 13px;
    font-weight: 600;
    color: #263238;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.cop-valor {
    flex: 0 0 auto;
    font-size: 13px;
    font-weight: 700;
    font-variant-numeric: tabular-nums;
    min-width: 60px;
    text-align: right;
}
.cop-valor.cop-valor-suma { color: #0d47a1; }
.cop-valor.cop-valor-resta { color: #b71c1c; }
.cop-selector {
    flex: 0 0 auto;
    display: flex;
    border: 1px solid #607d8b;
    border-radius: 4px;
    overflow: hidden;
}
.cop-btn {
    border: none;
    background: #ffffff;
    color: #455a64;
    font-size: 12px;
    font-weight: 700;
    padding: 5px 10px;
    cursor: pointer;
    font-family: inherit;
}
.cop-btn + .cop-btn { border-left: 1px solid #607d8b; }
.cop-btn:hover { background: #eceff1; }
.cop-btn-suma.cop-activo { background: #0d47a1; color: #ffffff; }
.cop-btn-resta.cop-activo { background: #b71c1c; color: #ffffff; }
/* Solo atenúa mientras guarda -- ¡OJO! antes tenía "pointer-events: none",
   pero si por lo que sea la petición de guardado nunca llegaba a resolverse
   (ni éxito ni error), esta clase se quedaba pegada para siempre y dejaba el
   widget sordo a cualquier clic a partir de ahí. Ahora solo es un aviso
   visual, nunca bloquea la interacción. */
.cop-guardando { opacity: 0.55; }

descriptor.controllerScript:
// ============================================================
// Widget "Caudalímetros del grupo": lee los caudalímetros asociados al
// Grupo_Riego actual (a través del ALIAS DE ENTIDAD configurado en la
// pestaña Datos de este widget -- debe apuntar a las entidades
// relacionadas, tipo "Caudalimetro"). Si hay más de uno, muestra el valor
// de cada uno con un selector +Suma / -Resta, para elegir cómo se combinan.
//
// DÓNDE SE GUARDA el signo elegido: NO en cada caudalímetro, sino en un
// único atributo del propio Grupo_Riego, "operaciones_caudalimetros"
// (mapa nombre_caudalimetro -> "suma"/"resta"). Se hizo así (en vez de un
// atributo por caudalímetro) porque en la cadena de reglas es mucho más
// simple leer UN atributo del Grupo_Riego que tener que ir a buscar el
// atributo de cada caudalímetro relacionado uno a uno. El resultado para
// el usuario es el mismo: se configura "por caudalímetro" desde este
// widget, solo cambia dónde vive el dato por debajo.
//
// v2.4 -- IMPORTANTE: este signo YA NO alimenta solo una telemetría aparte
// ("caudal_operaciones"). Desde la cadena de reglas Pila_de_Datos_v2.4, es
// el caudal REAL del Grupo_Riego: caudal_Sum, caudal_fijado, la media
// proyectada (y los acumulados caudal_total_diario_m3 / anual / total en
// m3) se calculan ya con este signo aplicado. En otras palabras: lo que
// se elige aquí deja de ser una cifra especial en paralelo y pasa a ser
// el caudal que ve todo el resto del sistema (paneles, facturación,
// proyecciones). Los caudalímetros individuales (su propia telemetría
// "caudal", vista aparte) siguen siendo siempre la lectura física real,
// sin signo -- lo que cambia con +Suma/-Resta es solo cómo se combinan
// dentro de su Grupo_Riego.
//
// La cadena de reglas (pila_de_datos) lee ese mismo atributo y el de
// cada caudalímetro para ir sumando/restando en los atributos-mapa
// "mapa_caudal_operaciones" (y sus equivalentes de volumen diario/anual/
// total) y publicar caudal_Sum / caudal_operaciones / caudal_total_diario_m3
// / caudal_total_anual_m3 / caudal_total_m3 en el Grupo_Riego cada vez que
// llega una lectura nueva.
// ============================================================
self.onInit = function() {
    const $ctx = self.ctx;
    const $container = $ctx.$container;
    const $lista = $container.find('#cop-lista');
    const $total = $container.find('#cop-total');
    const $btnRefrescar = $container.find('#cop-btn-refrescar');

    let caudalimetros = [];   // [{id, entityType, nombre, valor, signo}]
    let grupoRiegoId = null;
    let grupoRiegoType = null;

    function parseObj(value) {
        if (!value) { return {}; }
        if (typeof value === 'string') {
            try { return JSON.parse(value); } catch (e) { return {}; }
        }
        if (typeof value === 'object') { return value; }
        return {};
    }

    // Busca el Grupo_Riego relacionado con un caudalímetro, siguiendo la
    // misma relación "Forma_parte_de" que crea la cadena de reglas
    // (caudalimetro --Forma_parte_de--> Grupo_Riego).
    //
    // El primer intento (solo "fromId" de la entidad, y solo un salto vía
    // "Contains") no encontró nada: la entidad enlazada por "Contains" no
    // tenía NINGUNA relación de salida. Eso puede deberse a dos cosas
    // distintas, y no podíamos distinguirlas sin mirar también las
    // relaciones "de entrada" (toId):
    //   1) La relación existe pero en sentido contrario al que
    //      suponíamos (Grupo_Riego --Forma_parte_de--> Caudalimetro, en
    //      vez de Caudalimetro --Forma_parte_de--> Grupo_Riego).
    //   2) La relación sencillamente NO EXISTE todavía para este
    //      caudalímetro (el nodo de la cadena de reglas que la crea pudo
    //      haber fallado y haber disparado la alarma "Caudalimetro sin
    //      vincular" en su lugar).
    // Para cubrir el caso 1 sin adivinar, esta versión explora TODAS las
    // relaciones de cada entidad (tanto donde es "from" como donde es
    // "to"), y va saltando a través de cualquier relación "Contains" a
    // otras entidades no visitadas todavía (también en ambos sentidos),
    // hasta un máximo de pasos de seguridad. Si tras eso no aparece
    // ninguna "Forma_parte_de" hacia/desde un ASSET, es que el caso 2 es
    // el real: a este caudalímetro sencillamente no se le ha creado
    // todavía la relación con su Grupo_Riego en ThingsBoard.
    function buscarRelacionesDe(entidad, onDone) {
        const urlFrom = '/api/relations?fromId=' + entidad.id + '&fromType=' + entidad.entityType + '&relationTypeGroup=COMMON';
        const urlTo = '/api/relations?toId=' + entidad.id + '&toType=' + entidad.entityType + '&relationTypeGroup=COMMON';
        let pendientes = 2;
        let todas = [];
        function combinar(rels) {
            todas = todas.concat(rels || []);
            pendientes--;
            if (pendientes <= 0) { onDone(todas); }
        }
        console.log('[Caudalímetros del grupo] Pidiendo relaciones (from y to) para', entidad);
        $ctx.http.get(urlFrom).subscribe(function(rels) {
            console.log('[Caudalímetros del grupo] Relaciones "from" de ' + entidad.id + ': ' + JSON.stringify(rels));
            combinar(rels);
        }, function(err) {
            console.error('[Caudalímetros del grupo] Error HTTP (from) para', entidad, ':', err);
            combinar([]);
        });
        $ctx.http.get(urlTo).subscribe(function(rels) {
            console.log('[Caudalímetros del grupo] Relaciones "to" de ' + entidad.id + ': ' + JSON.stringify(rels));
            combinar(rels);
        }, function(err) {
            console.error('[Caudalímetros del grupo] Error HTTP (to) para', entidad, ':', err);
            combinar([]);
        });
    }

    function buscarGrupoRiego(entidadInicial, onOk, onErr) {
        const visitados = {};
        visitados[entidadInicial.entityType + ':' + entidadInicial.id] = true;
        const cola = [entidadInicial];
        const MAX_PASOS = 8; // límite de seguridad para no encadenar saltos sin fin
        let pasos = 0;

        function siguiente() {
            if (cola.length === 0 || pasos >= MAX_PASOS) {
                console.warn('[Caudalímetros del grupo] No se encontró ninguna relación "Forma_parte_de" hacia/desde un ASSET tras explorar ' + pasos + ' entidad(es). Lo más probable es que a este caudalímetro no se le haya creado todavía la relación con su Grupo_Riego (revisa si tiene la alarma "Caudalimetro sin vincular").');
                onErr();
                return;
            }
            pasos++;
            const entidad = cola.shift();
            buscarRelacionesDe(entidad, function(rels) {
                // Caso directo: la propia entidad participa en una
                // "Forma_parte_de" con un ASSET, en cualquiera de los dos
                // sentidos de la relación.
                const relSaliente = rels.find(function(r) {
                    return r.type === 'Forma_parte_de' && r.from && r.from.id === entidad.id && r.to && r.to.entityType === 'ASSET';
                });
                if (relSaliente) { onOk(relSaliente.to.id, relSaliente.to.entityType); return; }
                const relEntrante = rels.find(function(r) {
                    return r.type === 'Forma_parte_de' && r.to && r.to.id === entidad.id && r.from && r.from.entityType === 'ASSET';
                });
                if (relEntrante) { onOk(relEntrante.from.id, relEntrante.from.entityType); return; }

                // Si no, seguimos explorando a través de cualquier
                // relación "Contains" (en cualquier sentido) hacia otra
                // entidad todavía no visitada.
                rels.forEach(function(r) {
                    if (r.type !== 'Contains') return;
                    let vecino = null;
                    if (r.from && r.from.id === entidad.id) { vecino = r.to; }
                    else if (r.to && r.to.id === entidad.id) { vecino = r.from; }
                    if (!vecino) return;
                    const clave = vecino.entityType + ':' + vecino.id;
                    if (visitados[clave]) return;
                    visitados[clave] = true;
                    cola.push({ id: vecino.id, entityType: vecino.entityType });
                });
                siguiente();
            });
        }
        siguiente();
    }

    function obtenerValorCaudal(entidad, onDone) {
        const url = '/api/plugins/telemetry/' + entidad.entityType + '/' + entidad.id + '/values/timeseries?keys=caudal&limit=1';
        $ctx.http.get(url).subscribe(function(data) {
            const arr = data && data.caudal;
            const val = (arr && arr.length > 0) ? parseFloat(arr[0].value) : null;
            onDone(isNaN(val) ? null : val);
        }, function() { onDone(null); });
    }

    function obtenerSignos(onDone) {
        if (!grupoRiegoId) { onDone({}); return; }
        const url = '/api/plugins/telemetry/' + grupoRiegoType + '/' + grupoRiegoId + '/values/attributes/SERVER_SCOPE?keys=operaciones_caudalimetros';
        $ctx.http.get(url).subscribe(function(data) {
            const attr = (data || []).find(function(a) { return a.key === 'operaciones_caudalimetros'; });
            onDone(attr ? parseObj(attr.value) : {});
        }, function() { onDone({}); });
    }

    function guardarSignos(signos, onOk, onErr) {
        if (!grupoRiegoId) {
            console.warn('[Caudalímetros del grupo] No se puede guardar: aún no se ha resuelto el Grupo_Riego relacionado.');
            if (onErr) onErr();
            return;
        }
        // Red de seguridad: si por lo que sea la petición no llega a llamar
        // ni a onOk ni a onErr (nunca debería pasar, pero mejor curarse en
        // salud), esto asegura que el widget no se quede "colgado" en el
        // estado de guardando para siempre.
        let yaResuelto = false;
        const avisarUnaVez = function(fn) {
            return function() {
                if (yaResuelto) return;
                yaResuelto = true;
                fn.apply(null, arguments);
            };
        };
        const okSeguro = avisarUnaVez(onOk);
        const errSeguro = avisarUnaVez(onErr || function() {
            console.error('[Caudalímetros del grupo] No se pudo guardar el cambio de suma/resta.');
        });
        setTimeout(errSeguro, 10000);
        const payload = { operaciones_caudalimetros: JSON.stringify(signos) };
        try {
            $ctx.http.post('/api/plugins/telemetry/' + grupoRiegoType + '/' + grupoRiegoId + '/SERVER_SCOPE', payload).subscribe(okSeguro, errSeguro);
        } catch (e) {
            console.error('[Caudalímetros del grupo] Excepción al guardar:', e);
            errSeguro();
        }
    }

    function calcularTotal() {
        let total = 0;
        let algunDato = false;
        caudalimetros.forEach(function(c) {
            if (c.valor === null) return;
            algunDato = true;
            total += (c.signo === 'resta') ? -c.valor : c.valor;
        });
        return algunDato ? Math.round(total * 1000) / 1000 : null;
    }

    function pintarTotal() {
        if (caudalimetros.length <= 1) { $total.text(''); return; }
        const total = calcularTotal();
        $total.text(total === null ? '' : 'Total: ' + total + ' L/s');
    }

    function pintarLista() {
        $lista.empty();
        if (caudalimetros.length === 0) {
            $lista.append('<div class="cop-vacio">No hay caudalímetros vinculados a este grupo.<br>Configura el alias de entidad en la pestaña "Datos" del widget.</div>');
            pintarTotal();
            return;
        }
        if (caudalimetros.length === 1) {
            const c = caudalimetros[0];
            const $fila = $(
                '<div class="cop-fila-unica">' +
                '<span class="cop-nombre"></span>' +
                '<span class="cop-valor">' + (c.valor === null ? '-' : c.valor + ' L/s') + '</span>' +
                '</div>'
            );
            $fila.find('.cop-nombre').text(c.nombre);
            $lista.append($fila);
            pintarTotal();
            return;
        }
        caudalimetros.forEach(function(c) {
            const $fila = $(
                '<div class="cop-fila" data-nombre="">' +
                '<span class="cop-nombre"></span>' +
                '<span class="cop-valor"></span>' +
                '<div class="cop-selector">' +
                '<button type="button" class="cop-btn cop-btn-suma" data-signo="suma">+ Suma</button>' +
                '<button type="button" class="cop-btn cop-btn-resta" data-signo="resta">− Resta</button>' +
                '</div>' +
                '</div>'
            );
            $fila.attr('data-nombre', c.nombre);
            $fila.find('.cop-nombre').text(c.nombre).attr('title', c.nombre);
            $fila.find('.cop-valor')
                .text(c.valor === null ? '-' : c.valor + ' L/s')
                .toggleClass('cop-valor-suma', c.signo !== 'resta')
                .toggleClass('cop-valor-resta', c.signo === 'resta');
            $fila.find('.cop-btn-suma').toggleClass('cop-activo', c.signo !== 'resta');
            $fila.find('.cop-btn-resta').toggleClass('cop-activo', c.signo === 'resta');
            $lista.append($fila);
        });
        pintarTotal();
    }

    // Delegado UNA sola vez sobre #cop-lista (no dentro de pintarLista, que
    // se llama muchas veces) -- así no depende de volver a enganchar el
    // evento en cada repintado, y sigue funcionando aunque las filas se
    // reconstruyan continuamente.
    $lista.on('click', '.cop-btn', function() {
        const nuevoSigno = $(this).data('signo');
        const $fila = $(this).closest('.cop-fila');
        const nombre = $fila.attr('data-nombre');
        const c = caudalimetros.find(function(x) { return x.nombre === nombre; });
        if (!c || c.signo === nuevoSigno) return;
        const signoAnterior = c.signo;
        c.signo = nuevoSigno;
        pintarLista();
        $lista.addClass('cop-guardando');
        const signosActuales = {};
        caudalimetros.forEach(function(x) { signosActuales[x.nombre] = x.signo; });
        guardarSignos(signosActuales, function() {
            $lista.removeClass('cop-guardando');
        }, function() {
            c.signo = signoAnterior; // revertir si falla el guardado
            pintarLista();
            $lista.removeClass('cop-guardando');
        });
    });

    function cargarTodo() {
        $btnRefrescar.prop('disabled', true);
        const datasources = ($ctx.datasources || []).filter(function(d) { return d.entityId; });
        if (datasources.length === 0) {
            caudalimetros = [];
            grupoRiegoId = null;
            $lista.empty().append('<div class="cop-vacio">No hay ningún alias de entidad de caudalímetros configurado.<br>Ve a la pestaña "Datos" de este widget y añade el alias.</div>');
            $btnRefrescar.prop('disabled', false);
            return;
        }
        const entidades = datasources.map(function(d) {
            return { id: d.entityId, entityType: d.entityType, nombre: d.entityName };
        });
        const resultados = entidades.map(function(e) { return { id: e.id, entityType: e.entityType, nombre: e.nombre, valor: null, signo: 'suma' }; });

        // Dos "puertas" independientes tienen que terminar antes de poder
        // pintar de forma fiable: (1) los valores de caudal de cada
        // caudalímetro, y (2) encontrar el Grupo_Riego relacionado (para
        // poder leer y luego guardar los signos). Antes se pintaba en
        // cuanto (1) terminaba, sin esperar a (2) -- si los valores volvían
        // más rápido que la búsqueda del grupo, se pintaba con los signos
        // guardados sin cargar todavía (parecía que todo estaba en "Suma"
        // aunque hubieras guardado "Resta" antes) y, más grave, el botón
        // podía quedarse guardando sin saber aún en qué Grupo_Riego hacerlo.
        let valoresListos = false;
        let grupoResuelto = false;

        function pintarSiListo() {
            if (!valoresListos || !grupoResuelto) return;
            caudalimetros = resultados;
            function conSignos(signos) {
                caudalimetros.forEach(function(c) {
                    if (signos[c.nombre] === 'resta') { c.signo = 'resta'; }
                });
                pintarLista();
                $btnRefrescar.prop('disabled', false);
            }
            if (grupoRiegoId) {
                obtenerSignos(conSignos);
            } else {
                conSignos({});
            }
        }

        let pendientesValores = entidades.length;
        resultados.forEach(function(res, idx) {
            obtenerValorCaudal(entidades[idx], function(valor) {
                res.valor = valor;
                pendientesValores--;
                if (pendientesValores <= 0) { valoresListos = true; pintarSiListo(); }
            });
        });

        // El Grupo_Riego se determina a partir del PRIMER caudalímetro de la
        // lista (todos deberían pertenecer al mismo grupo, al ser el mismo
        // alias). Se resuelve en paralelo con los valores.
        buscarGrupoRiego(entidades[0], function(id, type) {
            grupoRiegoId = id;
            grupoRiegoType = type;
            grupoResuelto = true;
            pintarSiListo();
        }, function() {
            grupoRiegoId = null;
            grupoResuelto = true;
            console.warn('[Caudalímetros del grupo] No se encontró el Grupo_Riego relacionado (relación "Forma_parte_de") -- no se podrá guardar la configuración de suma/resta.');
            pintarSiListo();
        });
    }

    $btnRefrescar.off('click').on('click', cargarTodo);

    // Ya no se usa el datasource suscrito para pintar en vivo (los valores
    // se piden por API directa, igual que en el resto de widgets de este
    // dashboard) -- se deja como no-op por si el widget mantiene datos
    // configurados en la pestaña Datos.
    self.onDataUpdated = function() {};

    cargarTodo();
};

self.onDestroy = function() {};

